package com.steady.scheduler;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import java.io.*;
import java.nio.file.*;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class WebCompatibilityTest {
 @Test public void androidReadsWebEditedSnapshot() throws Exception {
  Path file=Paths.get("build/interop/web.zip");
  // Fixture is generated by npm test after BackupTest exports the Android source snapshot.
  Assume.assumeTrue("Run web tests to generate the return fixture",Files.isRegularFile(file));
  BackupTest fixture=new BackupTest();fixture.setup();
  try(InputStream input=Files.newInputStream(file)){
   PortableBackup.restore(fixture.store,fixture.files,input);
   assertTrue(fixture.store.items().stream().anyMatch(i->i.title.equals("Edited on web")));
   assertEquals(2,fixture.store.items().size());assertEquals("Solar rover",fixture.store.projects().get(0).title);
   assertEquals("Motor tested",fixture.store.journals().get(0)[2]);
   assertArrayEquals(new byte[]{1,2,3,4},Files.readAllBytes(new File(fixture.files,fixture.store.journalPhotos(Long.parseLong(fixture.store.journals().get(0)[6])).get(0)).toPath()));
  }finally{fixture.close();}
 }
}
